import Vue from 'vue'
import VueRouter from 'vue-router'

Vue.use(VueRouter)

const routes = [
  { path: '/login', name: 'Login', component: () => import('@/views/Login.vue'), meta: { guest: true } },
  {
    path: '/',
    component: () => import('@/layouts/UserLayout.vue'),
    meta: { role: 'USER' },
    children: [
      { path: '', name: 'Home', component: () => import('@/views/user/Home.vue') },
      { path: 'products', name: 'AllProducts', component: () => import('@/views/user/AllProducts.vue') },
      { path: 'products/:id', name: 'ProductDetail', component: () => import('@/views/user/ProductDetail.vue') },
      { path: 'cart', name: 'Cart', component: () => import('@/views/user/Cart.vue') },
      { path: 'favorite', name: 'Favorite', component: () => import('@/views/user/Favorite.vue') },
      { path: 'orders', name: 'MyOrders', component: () => import('@/views/user/MyOrders.vue') },
      { path: 'new', name: 'NewArrivals', component: () => import('@/views/user/NewArrivals.vue') },
      { path: 'recommend', name: 'Recommend', component: () => import('@/views/user/Recommend.vue') },
      { path: 'category/:id', name: 'Category', component: () => import('@/views/user/Category.vue') },
      { path: 'rank', name: 'SalesRank', component: () => import('@/views/user/SalesRank.vue') },
      { path: 'news', name: 'News', component: () => import('@/views/user/News.vue') },
      { path: 'announcements', name: 'Announcements', component: () => import('@/views/user/Announcements.vue') }
    ]
  },
  {
    path: '/admin',
    component: () => import('@/layouts/AdminLayout.vue'),
    meta: { role: 'ADMIN' },
    children: [
      { path: '', name: 'AdminDashboard', component: () => import('@/views/admin/Dashboard.vue') },
      { path: 'users', name: 'AdminUsers', component: () => import('@/views/admin/Users.vue') },
      { path: 'merchants', name: 'AdminMerchants', component: () => import('@/views/admin/Merchants.vue') },
      { path: 'categories', name: 'AdminCategories', component: () => import('@/views/admin/Categories.vue') },
      { path: 'products', name: 'AdminProducts', component: () => import('@/views/admin/Products.vue') },
      { path: 'orders', name: 'AdminOrders', component: () => import('@/views/admin/Orders.vue') },
      { path: 'news', name: 'AdminNews', component: () => import('@/views/admin/News.vue') }
    ]
  },
  {
    path: '/merchant',
    component: () => import('@/layouts/MerchantLayout.vue'),
    meta: { role: 'MERCHANT' },
    children: [
      { path: '', name: 'MerchantDashboard', component: () => import('@/views/merchant/Dashboard.vue') },
      { path: 'products', name: 'MerchantProducts', component: () => import('@/views/merchant/Products.vue') },
      { path: 'orders', name: 'MerchantOrders', component: () => import('@/views/merchant/Orders.vue') },
      { path: 'chat', name: 'MerchantChat', component: () => import('@/views/merchant/Chat.vue') }
    ]
  }
]

const router = new VueRouter({ mode: 'hash', base: process.env.BASE_URL, routes })

router.beforeEach((to, from, next) => {
  const user = JSON.parse(localStorage.getItem('user') || 'null')
  if (to.meta.guest) {
    if (user && user.token) {
      const role = user.role
      if (role === 'ADMIN') next('/admin')
      else if (role === 'MERCHANT') next('/merchant')
      else next('/')
    } else next()
    return
  }
  if (!user || !user.token) {
    next('/login')
    return
  }
  if (to.meta.role && to.meta.role !== user.role) {
    if (user.role === 'ADMIN') next('/admin')
    else if (user.role === 'MERCHANT') next('/merchant')
    else next('/')
    return
  }
  next()
})

export default router
